{ -------------------------------------------------------
    prepare selection indication geometry}
  BeginGroup;
    { 2D selection }
    Arc( -100, 100, 0, 360 );

{ 3D selection }
    BeginXtrd( ...
      ...
    EndXtrd;
  EndGroup;

{ set selection geometry for this object }
  result := SetCustomObjectSelectionGroup( objectHand, LNewObj );

